let blenderInfo={status:'unknown'},blenderJob=null,blenderQueue=[],blenderOpen=null,blenderLibrary={status:'unknown',packs:[],items:[]};const blenderChecking={};
const blenderCameras=[['orbit','Xoay quanh chủ thể'],['dolly','Tiến dần vào'],['pan','Lia ngang'],['crane','Nâng máy lên cao'],['static','Đứng yên']];
const blenderLights=[['day','Ban ngày'],['golden','Hoàng hôn'],['night','Ban đêm'],['studio','Studio sáng đều']];
const blenderFog={none:0,light:0.004,thick:0.009};
const blenderFilms=[['none','Không'],['film35','Phim 35mm · bạc, nhiễu hạt'],['bleach','Bạc màu chiến tranh'],['contrast','Tương phản mạnh']];
function blenderEffects(c){return {motionBlur:true,dof:true,shake:true,bloom:true,fog:'light',film:'none',...c.effects}}
function setBlenderEffect(cid,key,value){const c=blenderClip(project(),cid);if(!c)return;c.effects={...blenderEffects(c),[key]:value};save()}
const blenderModelHint='Nên dùng .glb hoặc .blend để giữ đủ chất liệu. File .gltf/.obj có texture rời có thể mất màu.';
function blenderClips(p){return p.blenderClips??(p.blenderClips=[])}
function blenderClip(p,cid){return blenderClips(p).find(c=>c.id===cid)}
function newBlenderClip(){const p=project(),list=blenderClips(p),c={id:id(),title:'Clip 3D '+(list.length+1),prompt:'',mode:'image',shots:[],overlays:{},camera:'orbit',lighting:'day',duration:6,quality:'draft',ground:true,useFileCamera:false,script:'',note:'',renders:[],created:new Date().toISOString()};list.unshift(c);blenderOpen=c.id;save();render()}
function removeBlenderClip(cid){const p=project(),c=blenderClip(p,cid);if(!c)return;if(blenderJob?.clipId===cid||c.ai?.status==='running')return toast('Clip đang render hoặc AI đang viết script.');if(!confirm('Xoá “'+c.title+'” khỏi danh sách? Video đã render vẫn còn trong timeline và kho video của dự án.'))return;p.blenderClips=blenderClips(p).filter(x=>x.id!==cid);save();render()}
function blenderAIBusy(){return state.projects.some(p=>(p.blenderClips||[]).some(c=>c.ai?.status==='running'||c.assetAI?.status==='running'||c.context?.status==='running'))}
function anyAIBusy(){return blenderAIBusy()||(typeof shortCutBusy==='function'&&shortCutBusy())||(typeof autoTagBusy==='function'&&autoTagBusy())||state.projects.some(p=>Object.values(p.guide?.steps||{}).some(s=>s.status==='running'))}
// "8–10 giây" in a shot list: the clip should last at least until the last beat.
function promptSeconds(text){let best=0;for(const m of String(text||'').matchAll(/(\d+(?:[.,]\d+)?)\s*(?:[–—-]\s*(\d+(?:[.,]\d+)?))?\s*(?:giây|s\b|sec)/gi)){const n=Number((m[2]||m[1]).replace(',','.'));if(n>best&&n<=30)best=n}return Math.ceil(best)}
function setBlender(cid,key,value){const p=project(),c=blenderClip(p,cid);if(!c)return;c[key]=key==='duration'?Math.min(30,Math.max(1,Math.round(Number(value)||6))):value;if(key==='prompt'){const need=promptSeconds(value);if(need>c.duration){c.duration=need;toast('Đã đặt thời lượng clip '+need+' giây theo mốc cuối trong mô tả.');render()}}save();if(key==='script')checkBlenderScript(p,c);if(['mode','useFileCamera','title','script'].includes(key))render()}
// Optional shortcut: start a clip's prompt from an existing scene's description.
function blenderPromptFromScene(cid,sid){const p=project(),c=blenderClip(p,cid),s=p.scenes.find(s=>s.id===sid);if(!c||!s)return;c.prompt=[s.image,s.video].filter(Boolean).join('\n\n')||s.voice||'';if(/^Clip 3D \d+$/.test(c.title))c.title=s.chapter||c.title;save();render()}
function blenderReady(c){if(c.mode==='image')return (c.shots||[]).length>0;return c.mode==='model'?!!c.modelPath:!!c.script?.trim()&&!blenderScriptProblems(c).length}
// The app checks scripts (parse only) with Blender's own Python before anything runs.
function blenderScriptProblems(c){return c.check?.script===c.script?(c.check.problems||[]):[]}
function blenderScriptChecked(c){return c.check?.script===c.script}
function checkBlenderScript(p,c){if(!native||!c.script?.trim()||blenderScriptChecked(c)||blenderChecking[c.id]===c.script)return;blenderChecking[c.id]=c.script;send('blenderCheck',{projectId:p.id,clipId:c.id,script:c.script})}
function fixBlenderProblems(cid){const c=blenderClip(project(),cid);if(!c)return;c.note='Script hiện tại bị app từ chối với các lỗi sau, hãy sửa hết và chỉ trả về code Python: '+blenderScriptProblems(c).join('; ');save();generateBlenderScript(cid)}
function chooseBlenderModel(cid){send('blenderModel',{projectId:project().id,clipId:cid})}
function generateBlenderScript(cid,chained=false){const p=project(),c=blenderClip(p,cid);if(!c)return;if(!c.prompt?.trim()&&!c.script?.trim())return toast('Viết mô tả cảnh muốn dựng trước.');if(anyAIBusy())return toast('AI đang xử lý một yêu cầu khác. Hãy đợi hoặc dừng lượt đó.');if(needsContext(c)&&!chained){if(!confirm('AI sẽ tra cứu bối cảnh trên web trước (sự kiện, xe, kiến trúc…), rồi viết script dựng cảnh cho “'+c.title+'”.\n\nDùng hạn mức Codex. Chưa render.'))return;return researchBlenderContext(cid,'script')}if(!chained&&!confirm('Dùng tài khoản ChatGPT đã kết nối để '+(c.script?'sửa':'viết')+' script dựng cảnh 3D cho “'+c.title+'”?\n\nDùng hạn mức Codex. Chưa render; bạn xem script trước khi chạy.'))return;c.ai={requestId:id(),status:'running',message:'AI đang viết script dựng cảnh…'};save();render();send('assistantGenerate',{requestId:c.ai.requestId,projectId:p.id,stage:'blender_script',context:{projectTitle:p.title,clipTitle:c.title,prompt:c.prompt||'',visualPromptBrief:visualPromptBrief(p),duration:c.duration,aspectRatio:projectAspect(p),camera:c.camera,lighting:c.lighting,previousScript:c.script||'',feedback:c.note||'',library:aiLibraryContext(),background:c.context?.text||''}})}
const originalBlenderAssistant=window.nativeAssistant;
window.nativeAssistant=function(r){if(r.stage!=='blender_script')return originalBlenderAssistant(r);const p=state.projects.find(p=>p.id===r.projectId),c=(p?.blenderClips||[]).find(c=>c.ai?.requestId===r.requestId);if(!c)return;const a=c.ai;a.message=r.message||a.message;if(r.status==='running'){const el=document.getElementById('blender-ai-'+c.id);if(el)el.textContent=a.message;return}a.status=r.status;if(r.status==='completed'&&r.result?.document){const code=String(r.result.document).replace(/^```(?:python)?\s*\n?/,'').replace(/\n?```\s*$/,'');if(c.script?.trim())c.previousScript=c.script;c.script=code;c.scriptTitle=r.result.title||'';a.message=(r.result.message||'Đã có script.')+' Xem script rồi bấm Render.';checkBlenderScript(p,c)}save();render();if(['error','interrupted'].includes(a.status))toast(a.message)};
function blenderSignature(c){return JSON.stringify([c.mode,c.mode==='image'?[c.shots,c.overlays]:c.mode==='model'?c.modelPath:c.script,c.camera,c.lighting,c.duration,c.quality,c.ground,c.useFileCamera,blenderEffects(c)])}
function startBlenderRender(p,c,preview=false){const fx=blenderEffects(c),body={requestId:id(),projectId:p.id,clipId:c.id,mode:c.mode,shots:(c.shots||[]).map(s=>({path:s.path,seconds:Number(s.seconds)||3,move:s.move||'push',parallax:s.parallax!==false,flashes:String(s.flashes||'').split(/[,;\s]+/).map(Number).filter(n=>Number.isFinite(n)&&n>=0)})),overlays:c.overlays||{},modelPath:c.modelPath,script:c.script,useFileCamera:!!c.useFileCamera,ground:c.ground!==false,duration:Number(c.duration)||6,fps:24,aspectRatio:projectAspect(p),quality:preview?'draft':c.quality,camera:c.camera,lighting:c.lighting,effects:{motionBlur:!!fx.motionBlur,dof:!!fx.dof,shake:!!fx.shake,bloom:!!fx.bloom,fog:blenderFog[fx.fog]??0,film:fx.film},models:libraryModelPaths(),preview};blenderJob={requestId:body.requestId,projectId:p.id,clipId:c.id,signature:blenderSignature(c),preview,status:'starting',progress:0,message:preview?'Đang render khung xem trước…':'Đang mở Blender…'};send('blenderRender',body)}
// Full-clip time from the preview's speed; Đẹp renders twice the pixels with more samples.
function blenderEstimate(c){const spf=c.preview?.secondsPerFrame;if(!spf)return '';const total=spf*(c.quality==='eevee'?6:1)*Math.round((Number(c.duration)||6)*24)+20;return 'ước tính '+(total<90?Math.round(total)+' giây':Math.round(total/60)+' phút')+(c.quality==='eevee'?' ở chất lượng Đẹp':'')}
function previewBlender(cid){const p=project(),c=blenderClip(p,cid);if(!c)return;const issue=blenderCanRender(c);if(issue)return toast(issue);blenderQueue=[];startBlenderRender(p,c,true);render()}
function blenderCanRender(c){if(blenderJob)return 'Blender đang render. Đợi xong hoặc dừng render.';if(c.mode==='image'&&!(c.shots||[]).length)return 'Thêm ít nhất một ảnh cho clip.';if(c.mode==='script'&&blenderScriptProblems(c).length)return 'Script có lỗi, app chưa cho chạy. Sửa script hoặc nhờ AI sửa các lỗi.';if(blenderInfo.status!=='found')return 'Chưa tìm thấy Blender trên máy. Cài hoặc chọn Blender.app trước.';if(!blenderReady(c))return c.mode==='model'?'Chọn model 3D trước.':'Nhờ AI viết hoặc tự dán script dựng cảnh trước.';return ''}
function renderBlender(cid){const p=project(),c=blenderClip(p,cid);if(!c)return;const issue=blenderCanRender(c);if(issue)return toast(issue);if(c.mode==='image'&&(c.shots||[]).some(s=>!s.path))return toast('Có ảnh chưa sẵn sàng.');if(c.mode==='script'&&!confirm('Chạy script dựng cảnh “'+c.title+'” trong Blender?\n\nApp kiểm tra script trước, rồi chạy Blender trong môi trường giới hạn: không có mạng, không ghi file ra ngoài thư mục tạm. Hãy đọc script nếu bạn tự sửa.'))return;blenderQueue=[];startBlenderRender(p,c);render()}
function renderAllBlender(){const p=project(),list=blenderClips(p).filter(c=>blenderReady(c)&&!c.renders?.some(r=>r.signature===blenderSignature(c)));if(blenderJob)return toast('Blender đang render.');if(blenderInfo.status!=='found')return toast('Chưa tìm thấy Blender trên máy.');if(!list.length)return toast('Không có clip nào sẵn sàng mà chưa render với thiết lập hiện tại.');if(!confirm('Render lần lượt '+list.length+' clip bằng Blender trên máy? Script AI chạy trong môi trường giới hạn (không mạng, không ghi file ra ngoài). Mỗi clip có thể mất vài phút.'))return;blenderQueue=list.slice(1).map(c=>({pid:p.id,cid:c.id}));startBlenderRender(p,list[0]);render()}
function cancelBlender(){blenderQueue=[];send('blenderCancel')}
window.nativeBlender=function(r){if(['found','missing'].includes(r.status)){blenderInfo=r;render();return}if(r.status==='library'){blenderLibrary={...blenderLibrary,status:'ready',packs:r.packs||[],items:r.items||[],downloading:!!r.downloading};render();return}if(r.status==='libraryProgress'){blenderLibrary.message=r.message;const el=document.getElementById('blender-library-status');if(el)el.textContent=r.message;return}if(r.status==='model'&&r.library){addLibraryModelFile(r);return}if(['inspected','inspectFailed'].includes(r.status)){finishModelInspection(r);return}const p=state.projects.find(p=>p.id===r.projectId),c=p&&(p.blenderClips||[]).find(c=>c.id===r.clipId);if(['checked','uncheckable'].includes(r.status)){if(!c)return;const checked=blenderChecking[c.id];delete blenderChecking[c.id];if(checked!==c.script)return checkBlenderScript(p,c);c.check={script:checked,problems:r.status==='checked'?r.problems||[]:[],message:r.message||''};save();render();return}if(r.status==='model'){if(!c)return;c.modelPath=r.path;c.modelName=r.name;c.mode='model';if(/^Clip 3D \d+$/.test(c.title))c.title=r.name.replace(/\.[^.]+$/,'');save();render();return}if(r.status==='error'&&!r.requestId){toast(r.message);return}if(!blenderJob||blenderJob.requestId!==r.requestId){if(r.status==='error')toast(r.message);return}blenderJob={...blenderJob,status:r.status,message:r.message||blenderJob.message,progress:r.progress??blenderJob.progress};if(['starting','running'].includes(r.status)){const el=document.getElementById('blender-progress-'+r.clipId);if(el)el.textContent=blenderJob.message;const bar=document.getElementById('blender-bar-'+r.clipId);if(bar?.style)bar.style.width=Math.round((blenderJob.progress||0)*100)+'%';return}const signature=blenderJob.signature;blenderJob=null;if(c&&r.status==='preview'){c.preview={paths:r.paths||[],frames:r.frames||[],fps:r.fps||24,signature,secondsPerFrame:Number(r.secondsPerFrame)||0};const est=blenderEstimate(c);c.message=r.message+(est?' Render cả clip ('+est+') ':' ')+'Ổn thì bấm Render cả clip.';save();render();return}if(c){c.message=r.message||'';if(r.status==='completed'&&r.path){const video={id:id(),path:r.path,name:'3D · '+c.title,duration:r.duration,provider:'blender',blenderClipId:c.id,created:new Date().toISOString()};p.extraVideos??=[];p.extraVideos.push(video);c.renders??=[];c.renders.push({id:video.id,path:r.path,duration:r.duration,mode:c.mode,signature,created:video.created});c.message=r.message+' Xem thử, rồi chèn vào timeline hoặc gán cho một cảnh.'}}save();if(r.status==='error')toast(r.message);const next=r.status==='completed'?blenderQueue.shift():null;if(r.status!=='completed')blenderQueue=[];if(next){const np=state.projects.find(p=>p.id===next.pid),nc=np&&blenderClip(np,next.cid);if(nc)startBlenderRender(np,nc)}render()};
function blenderVideo(p,rid){return (p.extraVideos||[]).find(a=>a.id===rid)}
function insertBlenderRender(cid,rid){const p=project(),c=blenderClip(p,cid),a=blenderVideo(p,rid);if(!c||!a)return toast('Không tìm thấy video đã render.');const r=c.renders.find(x=>x.id===rid);if(r)r.inserted=(r.inserted||0)+1;insertTimelineEntries(p,timelineEntries(p).length,[{...a,id:id(),duration:a.duration,videoDuration:a.duration,trimStart:0,includeOriginalAudio:false}]);toast('Đã chèn “'+c.title+'” vào cuối timeline. Mở Video & xuất để dời vị trí.')}
function attachBlenderRender(cid,rid,sid){const p=project(),c=blenderClip(p,cid),a=blenderVideo(p,rid),s=p.scenes.find(s=>s.id===sid);if(!c||!a||!s)return;if(!confirm('Dùng clip “'+c.title+'” làm video của Cảnh '+(p.scenes.indexOf(s)+1)+'? Clip cũ của cảnh vẫn được giữ trong phiên bản, cần duyệt lại video cảnh này.'))return render();s.assets??={};s.assets.video??=[];s.assets.video.forEach(v=>v.selected=false);s.assets.video.push({id:id(),path:a.path,name:a.name,duration:a.duration,selected:true,provider:'blender',blenderClipId:c.id,created:new Date().toISOString()});invalidate(p,s,'video');const r=c.renders.find(x=>x.id===rid);if(r)r.attachedTo=s.id;save();render();toast('Đã gán clip cho Cảnh '+(p.scenes.indexOf(s)+1)+'. Duyệt video cảnh này ở bước Video & xuất.')}
function blenderStatusView(){const title='<h2>Blender trên máy</h2>';if(!native)return `<section class="panel">${title}<p class="hint">Bước này chỉ chạy trong app Sử Studio trên macOS.</p></section>`;if(blenderInfo.status==='unknown'){blenderInfo={status:'checking'};setTimeout(()=>send('blenderStatus'),0)}const i=blenderInfo;if(i.status==='checking')return `<section class="panel">${title}<p class="hint">Đang tìm Blender…</p></section>`;return i.status==='found'?`<section class="panel"><div class="row"><div class="grow"><h2>Blender ${esc(i.version)}</h2><p class="hint">${esc(i.path)} · Render trên máy, không tốn credit.${i.sandbox?' Chạy trong môi trường giới hạn: không mạng, không ghi file ra ngoài thư mục tạm.':''}</p></div><button onclick="send('blenderChoose')">Đổi Blender.app…</button></div></section>`:`<section class="panel"><h2>Chưa có Blender</h2><p class="hint">${esc(i.message||'Cài Blender 4.x/5.x (miễn phí) để render clip 3D trên máy.')} Sau khi cài, bấm Kiểm tra lại.</p><div class="row"><button class="primary" onclick="send('blenderDownload')">Mở trang tải Blender</button><button onclick="blenderInfo={status:'unknown'};render()">Kiểm tra lại</button><button onclick="send('blenderChoose')">Chọn Blender.app…</button></div></section>`}
function blenderScriptCheckView(c){if(!c.script?.trim())return '';const problems=blenderScriptProblems(c);if(!blenderScriptChecked(c))return `<p class="hint">${native?'Đang kiểm tra script…':'Script được kiểm tra khi chạy trong app.'}</p>`;if(!problems.length)return `<p class="hint blender-check ok">✓ Script hợp lệ, sẵn sàng render.${c.check.message?' '+esc(c.check.message):''}</p>`;return `<div class="note warn blender-check"><b>App chưa cho chạy script này (${problems.length} lỗi)</b><ul class="changelog-items">${problems.slice(0,6).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="row"><button class="ai" ${blenderJob||anyAIBusy()?'disabled':''} onclick="fixBlenderProblems('${c.id}')">✦ AI sửa các lỗi này</button></div></div>`}
function blenderEffectsView(c){const fx=blenderEffects(c),box=(key,label)=>`<label><input type="checkbox" ${fx[key]?'checked':''} onchange="setBlenderEffect('${c.id}','${key}',this.checked)"> ${label}</label>`;return `<div class="row blender-effects"><span class="hint">Hiệu ứng điện ảnh:</span>${box('motionBlur','Nhoè chuyển động')}${box('dof','Xoá phông')}${box('shake','Rung máy cầm tay')}${box('bloom','Phát sáng')}<label>Màu phim <select onchange="setBlenderEffect('${c.id}','film',this.value)">${blenderFilms.map(([v,l])=>`<option value="${v}" ${fx.film===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Sương mù <select onchange="setBlenderEffect('${c.id}','fog',this.value)">${[['none','Không'],['light','Nhẹ'],['thick','Dày']].map(([v,l])=>`<option value="${v}" ${fx.fog===v?'selected':''}>${l}</option>`).join('')}</select></label></div>`}
function blenderPreviewView(c){const v=c.preview;if(!v?.paths?.length)return '';const stale=v.signature!==blenderSignature(c);return `<div class="blender-preview"><p class="hint">Xem trước${stale?' (thiết lập đã đổi, bấm Xem trước lại)':''} · ${v.frames.map(f=>(Math.max(0,f-1)/(v.fps||24)).toFixed(1)+' giây').join(' · ')}</p><div class="blender-preview-strip">${v.paths.map(path=>`<img src="${esc(referenceImageURL({path}))}" alt="" loading="lazy">`).join('')}</div></div>`}
function blenderClipView(p,c){if(c.mode==='script')checkBlenderScript(p,c);const running=blenderJob?.clipId===c.id,ai=c.ai,aiRunning=ai?.status==='running',busy=!!blenderJob,ext=(c.modelName||'').split('.').pop().toLowerCase(),options=(list,value)=>list.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join(''),renders=(c.renders||[]).filter(r=>blenderVideo(p,r.id)),open=running||aiRunning||blenderOpen===c.id||!renders.length;return `<details class="panel blender-clip-card" ${open?'open':''} ontoggle="if(this.open)blenderOpen='${c.id}'"><summary><span class="grow"><b>${esc(c.title)}</b><small>${c.mode==='image'?(c.shots||[]).length+' ảnh':c.mode==='model'?'Model 3D'+(c.modelName?' · '+esc(c.modelName):''):'Từ prompt'} · ${c.mode==='image'?blenderImageSeconds(c):c.duration} giây · ${renders.length?renders.length+' bản render':blenderReady(c)?'Sẵn sàng render':c.mode==='script'&&blenderScriptProblems(c).length?'Script có lỗi':'Chưa có '+(c.mode==='model'?'model':'script')}</small></span>${running?'<span class="badge amber">Đang render</span>':''}</summary>
<div class="fields"><div class="field"><label>Tên clip</label><input value="${esc(c.title)}" onchange="setBlender('${c.id}','title',this.value.trim()||'Clip 3D')"></div><div class="field"><label>Nguồn</label><div class="blender-source row"><label><input type="radio" name="blender-mode-${c.id}" ${c.mode==='image'?'checked':''} onchange="setBlender('${c.id}','mode','image')"> Từ ảnh · đẹp nhất</label><label><input type="radio" name="blender-mode-${c.id}" ${c.mode==='script'?'checked':''} onchange="setBlender('${c.id}','mode','script')"> Từ prompt · AI dựng 3D</label><label><input type="radio" name="blender-mode-${c.id}" ${c.mode==='model'?'checked':''} onchange="setBlender('${c.id}','mode','model')"> Từ model 3D</label></div></div></div>
${c.mode==='image'?blenderImageView(p,c,busy):c.mode==='model'?`<div class="row"><button ${busy?'disabled':''} onclick="chooseBlenderModel('${c.id}')">${c.modelPath?'Đổi model…':'Chọn model 3D…'}</button><span class="hint grow">${c.modelName?esc(c.modelName):'.glb, .blend, .fbx, .obj, .usdz, .stl'}</span></div>${['gltf','obj'].includes(ext)?`<p class="hint">${blenderModelHint}</p>`:''}<div class="row"><label><input type="checkbox" ${c.ground!==false?'checked':''} onchange="setBlender('${c.id}','ground',this.checked)"> Thêm mặt đất</label>${ext==='blend'?`<label><input type="checkbox" ${c.useFileCamera?'checked':''} onchange="setBlender('${c.id}','useFileCamera',this.checked)"> Dùng camera trong file .blend</label>`:''}</div>`:`${blenderContextView(c)}<div class="field"><label>Mô tả cảnh muốn dựng</label><textarea ${aiRunning?'disabled':''} placeholder="Ví dụ: Bãi cọc gỗ nhọn dưới lòng sông Bạch Đằng lúc thủy triều rút, chiến thuyền lớn mắc cạn nghiêng ngả, thuyền nhỏ áp sát, trời chiều đỏ" onchange="setBlender('${c.id}','prompt',this.value)">${esc(c.prompt||'')}</textarea>${p.scenes.length?`<div class="row"><select class="blender-from-scene" onchange="if(this.value)blenderPromptFromScene('${c.id}',this.value)"><option value="">Lấy mô tả từ một cảnh có sẵn (tuỳ chọn)…</option>${p.scenes.map((s,i)=>`<option value="${s.id}">Cảnh ${i+1} · ${esc(s.chapter||'')}</option>`).join('')}</select></div>`:''}</div>${c.script?`<div class="field"><label>Góp ý để AI sửa script (tuỳ chọn)</label><textarea ${aiRunning?'disabled':''} placeholder="Ví dụ: thêm nhiều cọc hơn, thuyền lớn hơn, máy quay thấp sát mặt nước" onchange="setBlender('${c.id}','note',this.value)">${esc(c.note||'')}</textarea></div>`:''}<div class="row"><button ${c.assetAI?.status==='running'||busy||!c.prompt?.trim()?'disabled':''} onclick="suggestModelsForClip('${c.id}')">✦ AI đề xuất model cần tải</button><button class="ai" ${aiRunning||busy?'disabled':''} onclick="generateBlenderScript('${c.id}')">✦ ${c.script?'AI sửa script theo góp ý':'AI viết script dựng cảnh'}</button>${aiRunning?'<button class="danger" onclick="send(\'assistantCancel\')">Dừng</button>':''}<span id="blender-ai-${c.id}" class="hint grow" role="status">${esc(c.assetAI?.status==='running'?c.assetAI.message:ai?.message||c.assetAI?.message||'')}</span></div><details class="blender-script" ${c.script&&!renders.length?'open':''}><summary>Script Blender${c.scriptTitle?' · '+esc(c.scriptTitle):''} ${c.script?`(${c.script.split('\n').length} dòng)`:'(chưa có, có thể tự dán)'}</summary><textarea spellcheck="false" ${aiRunning?'disabled':''} placeholder="Script Python dựng cảnh, dùng các hàm ground(), water(), box(), cylinder(), cone(), sphere(), sun(), sky(), animate(), shot()…" onchange="setBlender('${c.id}','script',this.value)">${esc(c.script||'')}</textarea></details>${blenderScriptCheckView(c)}`}
${c.mode==='image'?'':`<div class="fields blender-options"><div class="field"><label>Máy quay</label><select onchange="setBlender('${c.id}','camera',this.value)">${options(blenderCameras,c.camera)}</select></div><div class="field"><label>Ánh sáng</label><select onchange="setBlender('${c.id}','lighting',this.value)">${options(blenderLights,c.lighting)}</select></div><div class="field"><label>Thời lượng (giây)</label><input type="number" min="1" max="30" step="1" value="${c.duration}" onchange="setBlender('${c.id}','duration',this.value)"></div><div class="field"><label>Chất lượng</label><select onchange="setBlender('${c.id}','quality',this.value)">${options([['draft','Nháp · nửa độ phân giải, ít mẫu'],['eevee','Đẹp · đủ độ phân giải']],c.quality)}</select></div></div>`}
${blenderEffectsView(c)}<div class="row"><button ${busy||!blenderReady(c)||blenderInfo.status!=='found'?'disabled':''} onclick="previewBlender('${c.id}')">Xem trước 4 khung</button><button class="primary" ${busy||!blenderReady(c)||blenderInfo.status!=='found'?'disabled':''} onclick="renderBlender('${c.id}')">Render cả clip · ${isShort(p)?'dọc 9:16':'ngang 16:9'}</button>${running?'<button class="danger" onclick="cancelBlender()">Dừng render</button>':''}<span class="grow"></span><button class="flat" ${running?'disabled':''} onclick="removeBlenderClip('${c.id}')">Xoá clip</button></div><p class="hint" id="blender-progress-${c.id}" role="status">${esc(running?blenderJob.message:c.message||'')}</p>${running?`<div class="blender-bar"><span id="blender-bar-${c.id}" style="width:${Math.round((blenderJob.progress||0)*100)}%"></span></div>`:''}
${blenderPreviewView(c)}${renders.length?`<div class="blender-clips">${renders.slice().reverse().map((r,i)=>{const a=blenderVideo(p,r.id),scene=p.scenes.find(s=>s.id===r.attachedTo);return `<div class="row blender-clip"><span class="grow"><b>Bản ${renders.length-i}</b> <small class="hint">${Number(r.duration||0).toFixed(1)} giây · ${r.mode==='model'?'model':'script AI'} · ${esc(String(r.created||'').slice(11,16))} ${esc(String(r.created||'').slice(0,10).split('-').reverse().join('/'))}${r.inserted?' · đã chèn timeline':''}${scene?' · gán Cảnh '+(p.scenes.indexOf(scene)+1):''}</small></span><button onclick="send('timeline',{command:'previewSource',path:'${esc(a.path)}'})">▶ Xem</button><button class="primary" onclick="insertBlenderRender('${c.id}','${r.id}')">Chèn vào timeline</button>${p.scenes.length?`<select class="blender-attach" onchange="if(this.value)attachBlenderRender('${c.id}','${r.id}',this.value)"><option value="">Gán cho cảnh…</option>${p.scenes.map((s,k)=>`<option value="${s.id}">Cảnh ${k+1} · ${esc(s.chapter||'')}</option>`).join('')}</select>`:''}</div>`}).join('')}</div>`:''}</details>`}
function blenderView(){const p=project(),list=blenderClips(p),ready=list.filter(c=>blenderReady(c)&&!c.renders?.some(r=>r.signature===blenderSignature(c))).length;return `<div class="top"><div><button class="back" onclick="go('projects')">← Tất cả dự án</button><div class="eyebrow">Bước riêng · tuỳ chọn</div><h1 style="margin-top:8px">Dựng 3D bằng Blender</h1><p class="muted" style="margin-top:10px">${esc(p.title)} · Render trên máy, không tốn credit · ${isShort(p)?'khung dọc 9:16':'khung ngang 16:9'}</p></div><button class="primary" onclick="newBlenderClip()">＋ Clip 3D mới</button></div><div class="ai-layout">${workflowNavigation(p,'blender')}<div class="ai-content">${blenderStatusView()}${blenderInfo.status==='found'?blenderLibraryView()+modelLibraryView()+modelFinderView():''}<section class="panel"><h2>Clip 3D của dự án</h2><p class="hint">Bước này độc lập, không cần storyboard. Mỗi clip có mô tả riêng: AI viết script dựng cảnh 3D low-poly từ mô tả, hoặc bạn dùng model 3D có sẵn (.glb, .blend…). Chọn máy quay, ánh sáng rồi Render. Video xong có thể chèn vào timeline, gán cho một cảnh, hoặc lấy lại sau từ ô ＋ trên timeline.</p><div class="row"><button class="primary" onclick="newBlenderClip()">＋ Clip 3D mới</button><button ${blenderJob||!ready||blenderInfo.status!=='found'?'disabled':''} onclick="renderAllBlender()">Render lần lượt các clip đã sẵn sàng (${ready})</button>${blenderJob?'<button class="danger" onclick="cancelBlender()">Dừng</button>':''}${blenderQueue.length?`<span class="hint">Còn ${blenderQueue.length} clip chờ</span>`:''}</div></section>${list.map(c=>blenderClipView(p,c)).join('')||'<div class="panel"><p class="hint">Chưa có clip 3D nào. Bấm “＋ Clip 3D mới”, mô tả cảnh muốn dựng rồi nhờ AI viết script.</p></div>'}</div></div>`}
const originalBlenderLoaded=window.nativeLoaded;window.nativeLoaded=function(r){for(const p of r.state?.projects||[])for(const c of p.blenderClips||[])if(c.ai?.status==='running'){c.ai.status='interrupted';c.ai.message='App đã mở lại khi AI đang viết script. Bấm viết lại.'}originalBlenderLoaded(r)};
// ---------- Poly Haven library (free CC0 skies, textures, plants and props) ----------
function requestBlenderLibrary(){if(native&&blenderLibrary.status==='unknown'){blenderLibrary.status='checking';setTimeout(()=>send('blenderLibrary'),0)}}
function downloadLibraryPack(pack){if(blenderLibrary.downloading)return;blenderLibrary.downloading=true;blenderLibrary.message='Đang bắt đầu tải…';send('blenderDownloadPack',{pack});render()}
function blenderLibraryView(){requestBlenderLibrary();const L=blenderLibrary,sizes={base:'~80 MB',nature:'~21 MB',props:'~20 MB'};return `<section class="panel blender-library"><h2>Thư viện miễn phí Poly Haven</h2><p class="hint">Bầu trời chụp thật (HDRI), chất liệu thật (bùn, đất rừng, gạch, gỗ…), cây cỏ và đạo cụ. Giấy phép CC0, tải một lần, dùng cho mọi dự án, không tốn phí. AI tự dùng những gì đã tải.</p><div class="blender-packs">${(L.packs.length?L.packs:[{key:'base',title:'Bầu trời và chất liệu',count:22,installed:0},{key:'nature',title:'Cây cỏ, đá',count:7,installed:0},{key:'props',title:'Đạo cụ',count:6,installed:0}]).map(p=>`<div class="blender-pack"><b>${esc(p.title)}</b><small>${p.installed}/${p.count} mục · ${sizes[p.key]||''}</small>${p.installed>=p.count?'<span class="badge">Đã tải</span>':`<button ${L.downloading||!native?'disabled':''} onclick="downloadLibraryPack('${p.key}')">${p.installed?'Tải nốt':'Tải về'}</button>`}</div>`).join('')}</div><p class="hint" id="blender-library-status" role="status">${esc(L.message||'')}</p></section>`}
// ---------- the user's own model library ----------
function modelLibrary(){return state.modelLibrary??(state.modelLibrary=[])}
function modelSlug(text){return String(text||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().replace(/\.[a-z0-9]+$/,'').replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,40)||'model'}
function uniqueModelName(base,except=null){let name=base,k=2;while(modelLibrary().some(m=>m.name===name&&m.id!==except))name=(base+'_'+k++).slice(0,40);return name}
function addLibraryModel(){if(blenderInfo.status!=='found')return toast('Cần Blender trên máy để đọc model.');send('blenderModel',{library:true})}
function addLibraryModelFile(r){if(!r.path)return;const m={id:id(),name:uniqueModelName(modelSlug(r.name)),title:String(r.name||'').replace(/\.[^.]+$/,''),description:'',path:r.path,fileName:r.name,status:'reading',message:'Đang đọc kích thước và bộ phận bằng Blender…',added:new Date().toISOString()};modelLibrary().unshift(m);save();render();send('blenderInspect',{modelId:m.id,path:m.path})}
function finishModelInspection(r){const m=modelLibrary().find(m=>m.id===r.modelId);if(!m)return;if(r.status==='inspected'){m.size=(r.size||[]).map(Number);m.parts=r.parts||[];m.animated=!!r.animated;m.status='ready';m.message=''}else{m.status='error';m.message=r.message||'Không đọc được model.'}save();render()}
function editLibraryModel(mid,key,value){const m=modelLibrary().find(m=>m.id===mid);if(!m)return;if(key==='name'){m.name=uniqueModelName(modelSlug(value),mid)}else m[key]=value;save();render()}
function removeLibraryModel(mid){const m=modelLibrary().find(m=>m.id===mid);if(!m||!confirm('Bỏ “'+m.name+'” khỏi kho model? File vẫn được giữ trong tài nguyên app.'))return;state.modelLibrary=modelLibrary().filter(x=>x.id!==mid);save();render()}
function libraryModelPaths(){return Object.fromEntries(modelLibrary().filter(m=>m.status==='ready').map(m=>[m.name,m.path]))}
function aiLibraryContext(){const items=blenderLibrary.items||[];return {skies:items.filter(i=>i.kind==='hdri').map(i=>({name:i.key,description:i.title})),textures:items.filter(i=>i.kind==='texture').map(i=>({name:i.key,description:i.title})),models:[...modelLibrary().filter(m=>m.status==='ready').map(m=>({name:m.name,description:[m.title,m.description].filter(Boolean).join(' — '),size:m.size,parts:(m.parts||[]).slice(0,25),animated:m.animated,source:'người dùng'})),...items.filter(i=>i.kind==='model').map(i=>({name:i.key,description:i.title,source:'Poly Haven'}))]}}
function modelLibraryView(){const list=modelLibrary();return `<section class="panel model-library"><div class="row"><div class="grow"><h2>Kho model của bạn</h2><p class="hint">Nhập model 3D (.glb khuyên dùng, .blend, .fbx…) tải từ Sketchfab, kho miễn phí hoặc tự làm: trực thăng, súng, người, xe, nhà… Đặt <b>tên ngắn</b> và <b>mô tả</b>; AI thấy danh sách này và đặt model vào cảnh thay cho khối tự dựng. Bộ phận có tên như “rotor”, “propeller” sẽ quay được.</p></div><div class="row"><button ${modelCredits().length?'':'disabled'} onclick="copyModelCredits()">Sao chép ghi nguồn model</button><button class="primary" ${blenderInfo.status!=='found'?'disabled':''} onclick="addLibraryModel()">＋ Thêm model…</button></div></div>${list.length?`<div class="model-list">${list.map(m=>`<div class="model-item"><div class="fields"><div class="field"><label>Tên cho AI</label><input value="${esc(m.name)}" onchange="editLibraryModel('${m.id}','name',this.value)"></div><div class="field"><label>Mô tả</label><input value="${esc(m.description||'')}" placeholder="Ví dụ: trực thăng UH-1 Huey thời chiến tranh Việt Nam" onchange="editLibraryModel('${m.id}','description',this.value)"></div></div><div class="row"><span class="hint grow">${m.credit?'Tác giả '+esc(m.credit.author)+' · '+esc(m.credit.license)+' · ':''}${esc(m.fileName||'')} · ${m.status==='ready'?(m.size||[]).map(v=>Number(v).toFixed(1)).join(' × ')+' m'+(m.parts?.length?' · '+m.parts.length+' bộ phận':'')+(m.animated?' · có chuyển động':''):esc(m.message||'')}</span><button class="flat" onclick="removeLibraryModel('${m.id}')">Bỏ khỏi kho</button></div></div>`).join('')}</div>`:'<p class="hint">Chưa có model nào. Gợi ý tên: huey, ak47, linh_my, chien_si, xe_tang_t54, nha_tranh.</p>'}</section>`}
// ---------- "Từ ảnh": beautiful stills (PlenX, ChatGPT…) turned into 2.5D camera moves with overlays ----------
const blenderMoves=[['push','Tiến vào'],['pull','Lùi ra'],['pan_left','Lia sang trái'],['pan_right','Lia sang phải'],['rise','Nâng máy lên'],['orbit','Xoay nhẹ quanh chủ thể'],['static','Gần như đứng yên']];
const blenderOverlays=[['smoke','Khói'],['fog','Sương trôi'],['dust','Bụi lơ lửng'],['embers','Tàn lửa'],['rain','Mưa']];
const blenderLevels=[[0,'Không'],[0.35,'Nhẹ'],[0.65,'Vừa'],[1,'Dày']];
function blenderImageSeconds(c){return Math.round((c.shots||[]).reduce((n,s)=>n+(Number(s.seconds)||3),0)*10)/10}
function projectImages(p){const seen=new Set(),list=[];p.scenes.forEach((s,i)=>(s.assets?.image||[]).forEach(a=>{if(a.path&&!seen.has(a.path)){seen.add(a.path);list.push({path:a.path,label:'Cảnh '+(i+1)+' · '+(s.chapter||'')+(a.selected?' (đang dùng)':''),name:a.name})}}));(p.blenderClips||[]).forEach(c=>(c.shots||[]).forEach(s=>{if(s.path&&!seen.has(s.path)){seen.add(s.path);list.push({path:s.path,label:'Clip 3D · '+c.title,name:s.name})}}));return list}
function addBlenderShot(cid,path,name){const p=project(),c=blenderClip(p,cid);if(!c||!path)return;c.shots??=[];c.shots.push({id:id(),path,name:name||'Ảnh',seconds:3,move:['push','pan_right','orbit','pull'][c.shots.length%4],parallax:true,flashes:''});save();render()}
function editBlenderShot(cid,sid,key,value){const c=blenderClip(project(),cid),s=c?.shots?.find(s=>s.id===sid);if(!s)return;s[key]=key==='seconds'?Math.min(30,Math.max(0.5,Number(value)||3)):value;save();if(key!=='flashes')render()}
function moveBlenderShot(cid,sid,delta){const c=blenderClip(project(),cid),i=c?.shots?.findIndex(s=>s.id===sid);if(i==null||i<0)return;const j=i+delta;if(j<0||j>=c.shots.length)return;[c.shots[i],c.shots[j]]=[c.shots[j],c.shots[i]];save();render()}
function removeBlenderShot(cid,sid){const c=blenderClip(project(),cid);if(!c)return;c.shots=(c.shots||[]).filter(s=>s.id!==sid);save();render()}
function setBlenderOverlay(cid,key,value){const c=blenderClip(project(),cid);if(!c)return;c.overlays={...c.overlays,[key]:Number(value)||0};save()}
function importBlenderShot(cid){send('asset',{request:{project:project().id,blenderClipId:cid,kind:'image'}})}
const originalBlenderAsset=window.nativeAsset;
window.nativeAsset=function(r){if(r.request?.blenderClipId){const p=state.projects.find(p=>p.id===r.request.project);if(!p)return;const keep=selected;selected=p.id;addBlenderShot(r.request.blenderClipId,r.path,r.name);selected=keep;return}originalBlenderAsset(r)};
// PlenX image straight from the clip's description (one image per call; uses PlenX credit).
function generateBlenderShotImage(cid,chained=false){const p=project(),c=blenderClip(p,cid),m=plenxImageModels.find(m=>m.id===p.plenxImageModel);if(!c)return;if(!c.prompt?.trim())return toast('Viết mô tả cảnh trước khi tạo ảnh.');if(!m)return toast('Chọn model ảnh PlenX ở ô bên dưới (bấm Tải danh sách model nếu trống).');if(plenxImagePending)return toast('PlenX đang xử lý một yêu cầu khác.');if(c.imageJob&&!['completed','failed','error'].includes(c.imageJob.status))return toast('Ảnh trước vẫn đang tạo.');if(needsContext(c)&&!chained){if(anyAIBusy())return toast('AI đang xử lý một yêu cầu khác.');if(!confirm('AI sẽ tra cứu bối cảnh trên web trước (dùng hạn mức Codex), rồi tạo 1 ảnh bằng '+m.name+' (dùng credit PlenX). Tiếp tục?'))return;return researchBlenderContext(cid,'image')}if(!chained&&!confirm('Tạo 1 ảnh bằng '+m.name+' từ mô tả của “'+c.title+'”? Dùng credit PlenX (rẻ hơn tạo video nhiều).'))return;c.imageJob={status:'submitting',message:'PlenX đang tạo ảnh…'};save();render();plenxImageRequest('generate',{projectId:p.id,blenderClipId:cid,model:m.id,resolution:m.resolutions?.[0]||'',prompt:'Ảnh điện ảnh chân thực '+frameLabel(p)+', một khung hình duy nhất, không chữ, không watermark, chủ thể rõ ràng tách khỏi nền, có tiền cảnh và hậu cảnh.\n'+c.prompt+(c.imageNote?'\n'+c.imageNote:'')+(c.context?.text?'\nBỐI CẢNH ĐÃ TRA CỨU (giữ đúng chi tiết):\n'+c.context.text.slice(0,1500):'')})}
function checkBlenderShotImage(pid,cid,attempt=0){const p=state.projects.find(p=>p.id===pid),c=p&&blenderClip(p,cid);if(!c?.imageJob?.taskId||c.imageJob.status==='completed')return;if(plenxImagePending){if(attempt<120)setTimeout(()=>checkBlenderShotImage(pid,cid,attempt+1),5000);return}plenxImageRequest('status',{projectId:pid,blenderClipId:cid,taskId:c.imageJob.taskId,attempt})}
const originalBlenderPlenx=window.nativePlenxImage;
window.nativePlenxImage=function(r){const pending=plenxImagePending;if(!pending?.blenderClipId)return originalBlenderPlenx(r);if(pending.requestId!==r.requestId)return;plenxImagePending=null;const p=state.projects.find(p=>p.id===pending.projectId),c=p&&(p.blenderClips||[]).find(c=>c.id===pending.blenderClipId);if(!c)return;c.imageJob??={};if(r.taskId)c.imageJob.taskId=r.taskId;c.imageJob.status=r.status;c.imageJob.message=r.message||'';if(r.status==='completed'&&r.path){c.shots??=[];c.shots.push({id:id(),path:r.path,name:r.name||'Ảnh PlenX',seconds:3,move:['push','pan_right','orbit','pull'][c.shots.length%4],parallax:true,flashes:'',provider:'plenx'});c.imageJob.message='Đã thêm ảnh PlenX vào clip.'}save();render();if(r.status==='queued'&&c.imageJob.taskId&&(pending.attempt||0)<120)setTimeout(()=>checkBlenderShotImage(p.id,c.id,(pending.attempt||0)+1),5000);if(['error','failed'].includes(r.status))toast(c.imageJob.message)};
function blenderImageView(p,c,busy){return blenderContextView(c)+blenderImageInner(p,c,busy)}
function blenderImageInner(p,c,busy){const images=projectImages(p),model=plenxImageModels.find(m=>m.id===p.plenxImageModel),job=c.imageJob,jobBusy=job&&!['completed','failed','error'].includes(job.status),levels=(key)=>blenderLevels.map(([v,l])=>`<option value="${v}" ${Number(c.overlays?.[key]||0)===v?'selected':''}>${l}</option>`).join('');return `<p class="hint">Dùng ảnh đẹp có sẵn (tạo bằng PlenX, ChatGPT…). Blender tạo chuyển động máy quay có chiều sâu 2.5D (tự tách chủ thể khỏi nền), phủ khói bụi, màu phim. Render nhanh, không tốn credit. Nhân vật trong ảnh không tự cử động.</p>
<div class="field"><label>Mô tả cảnh (để tạo ảnh PlenX)</label><textarea placeholder="Ví dụ: chiến sĩ đội mũ tai bèo ôm súng chạy trên đường bùn giữa rừng nhiệt đới, chiều u ám, khói mỏng" onchange="setBlender('${c.id}','prompt',this.value)">${esc(c.prompt||'')}</textarea></div>
<div class="row blender-add-shot"><select onchange="if(this.value){addBlenderShot('${c.id}',this.value,this.options[this.selectedIndex].text)}"><option value="">＋ Chọn ảnh có trong dự án…</option>${images.map(i=>`<option value="${esc(i.path)}">${esc(i.label)}</option>`).join('')}</select><button ${busy?'disabled':''} onclick="importBlenderShot('${c.id}')">＋ Nhập ảnh từ máy (ChatGPT…)</button><button class="ai" ${busy||jobBusy||!c.prompt?.trim()?'disabled':''} onclick="generateBlenderShotImage('${c.id}')">✦ Tạo ảnh bằng PlenX</button><select onchange="setPlenxImageModel(this.value)">${model?'':'<option value="">Model ảnh PlenX…</option>'}${plenxImageModels.filter(m=>!m.aspect_ratios||m.aspect_ratios.includes(projectAspect(p))).map(m=>`<option value="${esc(m.id)}" ${m.id===p.plenxImageModel?'selected':''}>${esc(m.name)}</option>`).join('')}</select>${plenxImageModels.length?'':`<button onclick="plenxImageRequest('models')">Tải danh sách model</button>`}</div>${job?.message?`<p class="hint" role="status">${esc(job.message)}</p>`:''}
${(c.shots||[]).length?`<div class="blender-shots">${c.shots.map((s,i)=>`<div class="blender-shot"><img src="${esc(referenceImageURL({path:s.path}))}" alt=""><div class="grow"><b>Đoạn ${i+1}</b> <small class="hint">${esc(s.name||'')}</small><div class="row"><select onchange="editBlenderShot('${c.id}','${s.id}','move',this.value)">${blenderMoves.map(([v,l])=>`<option value="${v}" ${s.move===v?'selected':''}>${l}</option>`).join('')}</select><label>Giây <input type="number" min="0.5" max="30" step="0.5" value="${s.seconds}" style="width:70px" onchange="editBlenderShot('${c.id}','${s.id}','seconds',this.value)"></label><label><input type="checkbox" ${s.parallax!==false?'checked':''} onchange="editBlenderShot('${c.id}','${s.id}','parallax',this.checked)"> Chiều sâu 2.5D</label><label>Chớp nổ ở giây <input value="${esc(s.flashes||'')}" placeholder="vd 1.2, 2" style="width:90px" onchange="editBlenderShot('${c.id}','${s.id}','flashes',this.value)"></label></div></div><div class="blender-shot-actions"><button class="flat" onclick="moveBlenderShot('${c.id}','${s.id}',-1)">↑</button><button class="flat" onclick="moveBlenderShot('${c.id}','${s.id}',1)">↓</button><button class="flat" onclick="removeBlenderShot('${c.id}','${s.id}')">Bỏ</button></div></div>`).join('')}</div><p class="hint">Tổng ${blenderImageSeconds(c)} giây · mỗi ảnh là một đoạn, cắt cảnh liền nhau.</p>`:'<p class="hint">Chưa có ảnh. Chọn ảnh trong dự án, nhập ảnh từ máy hoặc tạo bằng PlenX.</p>'}
<div class="row blender-effects"><span class="hint">Hiệu ứng phủ:</span>${blenderOverlays.map(([k,l])=>`<label>${l} <select onchange="setBlenderOverlay('${c.id}','${k}',this.value)">${levels(k)}</select></label>`).join('')}</div>`}
